      console.error(`FAIL: averageSpeed(${distanceKm}, ${hours}) = ${rounded}, expected ${expected}`);
    } else {
      console.log(`PASS: averageSpeed(${distanceKm}, ${hours}) = ${rounded}`);
    }
  }

  console.log('Self-test completed.');
}

